def f(x):
    x += 1
    while x % 10 == 0:
        x //= 10
    return x

def count_reachable_numbers(n):
    reachable = set()
    current = n

    while current not in reachable:
        reachable.add(current)
        current = f(current)

    # Now, we need to find all numbers that can be reached from any number in the cycle.
    full_set = set()
    for start in reachable:
        temp = start
        while temp not in full_set:
            full_set.add(temp)
            temp = f(temp)

    return len(full_set)

n = int(input())
print(count_reachable_numbers(n))
```

