def find_spanning_tree(n, m, D, edges):
    from collections import defaultdict

    # Create adjacency list for the graph
    adj = defaultdict(list)
    for v, u in edges:
        adj[v].append(u)
        adj[u].append(v)

    # Initialize variables to track the spanning tree and degree of vertex 1
    parent = {i: None for i in range(1, n + 1)}
    visited = set()
    degree_of_1 = 0

    def dfs(node):
        nonlocal degree_of_1
        visited.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                parent[neighbor] = node
                if node == 1:
                    degree_of_1 += 1
                dfs(neighbor)

    # Start DFS from vertex 1
    dfs(1)

    # Check if we have a valid spanning tree and the degree of vertex 1 is D
    if len(visited) != n or degree_of_1 != D:
        print("NO")
    else:
        print("YES")
        for i in range(2, n + 1):
            if parent[i] is not None:
                print(parent[i], i)

# Read input
n, m, D = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(m)]

find_spanning_tree(n, m, D, edges)
