import itertools

def find_valid_expressions():
    a, b, c, d = map(int, input().split())
    operators = ['+', '-', '*', '/']
    valid_expressions = []

    for op1, op2 in itertools.product(operators, repeat=2):
        try:
            if eval(f"{a} {op1} {b}") == eval(f"{c} {op2} {d}"):
                expression = f"{a} {op1} {b} = {c} {op2} {d}"
                valid_expressions.append(expression)
        except ZeroDivisionError:
            continue

    if valid_expressions:
        for expr in sorted(valid_expressions, key=lambda x: (x.replace('*', ' ').replace('+', ' ').replace('-', ' ').replace('/', ' '), x)):
            print(expr)
    else:
        print("problems ahead")

find_valid_expressions()
