def min_total_pairwise_distance(q, test_cases):
    results = []
    for i in range(q):
        a, b, c = sorted(test_cases[i])
        if a == b == c:
            results.append(0)
        else:
            # Try moving each friend by -1, 0, or +1
            min_distance = float('inf')
            for da in [-1, 0, 1]:
                for db in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        a_prime, b_prime, c_prime = a + da, b + db, c + dc
                        distance = abs(a_prime - b_prime) + abs(a_prime - c_prime) + abs(b_prime - c_prime)
                        min_distance = min(min_distance, distance)
            results.append(min_distance)
    return results

