def count_parking_spaces():
    R, C = map(int, input().split())
    grid = [input() for _ in range(R)]

    def is_valid(x, y):
        return 0 <= x < R and 0 <= y < C

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    squash_count = [0] * 5

    for i in range(R - 1):
        for j in range(C - 1):
            if grid[i][j] == '#' or grid[i+1][j] == '#' or grid[i][j+1] == '#' or grid[i+1][j+1] == '#':
                continue

            count = 0
            for dx, dy in directions:
                nx, ny = i + dx, j + dy
                if is_valid(nx, ny) and grid[nx][ny] == 'X':
                    count += 1
                nx, ny = i + dx + 1, j + dy + 1
                if is_valid(nx, ny) and grid[nx][ny] == 'X':
                    count += 1

            squash_count[count] += 1

    for num in squash_count:
        print(num)

