def color_array():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Dictionary to store indices of each number in the array
    index_dict = {}
    for i, num in enumerate(a):
        if num not in index_dict:
            index_dict[num] = []
        index_dict[num].append(i)

    # Check if any number appears more than k times
    if any(len(indices) > k for indices in index_dict.values()):
        print("NO")
        return

    # Initialize the result array with zeros
    colors = [0] * n

    # Assign colors to each element
    color_count = 1
    for num, indices in index_dict.items():
        for j in range(len(indices)):
            colors[indices[j]] = (j % k) + 1
            if color_count < k and j == len(indices) - 1:
                color_count += 1

    # Check if all colors are used at least once
    if max(colors) < k:
        print("NO")
    else:
        print("YES")
        print(' '.join(map(str, colors)))

color_array()
