        required = [0] * n
        for i in range(n):
            required[i] = int(capacities[i] / fraction) + (1 if capacities[i] % fraction != 0 else 0)

        required.sort()
        balloons = list(range(1, n + 1))
        balloons.sort(reverse=True)

        j = 0
        for i in range(n):
            while j < n and required[j] > balloons[i]:
                j += 1
            if j == n:
                return False
            j += 1
        return True

    low, high = 0, max(capacities)
    result = 0

    for _ in range(100):
        mid = (low + high) / 2
        if can_fill(mid):
            result = mid
            low = mid
        else:
            high = mid

    if result == 0:
        return "impossible"
    else:
        return f"{result:.6f}"

