def arcade_basketball_competition():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n, p, m = map(int, data[0].split())
    participants = {}

    for i in range(1, n + 1):
        name = data[i]
        participants[name] = 0

    winners = []
    winner_announced = set()

    for i in range(n + 1, n + m + 1):
        entry = data[i].split()
        name = entry[0]
        points = int(entry[1])

        if name in participants:
            participants[name] += points

            if participants[name] >= p and name not in winner_announced:
                winners.append(name)
                winner_announced.add(name)

    if winners:
        for winner in winners:
            print(f"{winner} wins!")
    else:
        print("No winner!")

arcade_basketball_competition()
