def find_sequences():
    n = int(input())
    a = list(map(int, input().split()))

    inc = -1  # Last element of increasing sequence
    dec = float('inf')  # Last element of decreasing sequence
    res = []

    for x in a:
        if inc < x < dec:
            if x > (res[-1] if res else -2):
                inc = x
                res.append(0)
            else:
                dec = x
                res.append(1)
        elif x == inc or x == dec:
            if x == inc:
                inc += 1
            else:
                dec -= 1
            res.append(res[-1])
        elif x > inc:
            inc = x
            res.append(0)
        elif x < dec:
            dec = x
            res.append(1)
        else:
            print("NO")
            return

    print("YES")
    print(' '.join(map(str, res)))

find_sequences()
