def restore_order(n, remembered):
    if n == 3:
        return [1, 2, 3]

    p = [0] * n
    a = [[0, 0] for _ in range(n + 1)]

    for i in range(1, n + 1):
        a[i][0], a[i][1] = remembered[i - 1]

    p[0], p[1], p[2] = 1, a[1][0], a[1][1]

    for i in range(3, n):
        if a[p[i-1]][0] == p[i-2] or a[p[i-1]][1] == p[i-2]:
            p[i] = a[p[i-1]][0]
        else:
            p[i] = a[p[i-1]][1]

    print(*p)

# Read input
n = int(input())
remembered = [tuple(map(int, input().split())) for _ in range(n)]

restore_order(n, remembered)
```

