    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def minimum_cost_to_connect_graph(n, m, a, offers):
    edges = []

    # Add all special offers as edges
    for x, y, w in offers:
        edges.append((w, x - 1, y - 1))

    # Find the vertex with the smallest value to connect all other vertices optimally
    min_value_vertex = a.index(min(a))

    # Add edges from this minimum value vertex to all others with cost a[min] + a[i]
    for i in range(n):
        if i != min_value_vertex:
            edges.append((a[min_value_vertex] + a[i], min_value_vertex, i))

    # Sort edges based on their weight
    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    total_cost = 0
    edges_used = 0

    for cost, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            total_cost += cost
            edges_used += 1
            if edges_used == n - 1:
                break

    return total_cost

# Read input
n, m = map(int, input().split())
a = list(map(int, input().split()))
offers = [tuple(map(int, input().split())) for _ in range(m)]

# Calculate and print the result
print(minimum_cost_to_connect_graph(n, m, a, offers))
