import sys
import bisect

def find_min_distance(A, B, Q, shrines, temples, queries):
    inf = float('inf')

    def distance(x, y):
        return abs(x - y)

    results = []

    for x in queries:
        min_dist = inf

        # Find the closest shrine to the left and right of x
        s_left_idx = bisect.bisect_right(shrines, x) - 1
        s_right_idx = s_left_idx + 1

        # Find the closest temple to the left and right of x
        t_left_idx = bisect.bisect_right(temples, x) - 1
        t_right_idx = t_left_idx + 1

        # Calculate all possible distances
        if s_left_idx >= 0:
            if t_left_idx >= 0:
                min_dist = min(min_dist, distance(x, shrines[s_left_idx]) + distance(shrines[s_left_idx], temples[t_left_idx]))
            if t_right_idx < B:
                min_dist = min(min_dist, distance(x, shrines[s_left_idx]) + distance(shrines[s_left_idx], temples[t_right_idx]))

        if s_right_idx < A:
            if t_left_idx >= 0:
                min_dist = min(min_dist, distance(x, temples[t_left_idx]) + distance(temples[t_left_idx], shrines[s_right_idx]))
            if t_right_idx < B:
                min_dist = min(min_dist, distance(x, temples[t_right_idx]) + distance(temples[t_right_idx], shrines[s_right_idx]))

        # Consider the case where we visit both shrine and temple on one side of x
        if s_left_idx >= 0 and t_right_idx < B:
            min_dist = min(min_dist, distance(shrines[s_left_idx], temples[t_right_idx]) + max(0, x - shrines[s_left_idx]))

        if s_right_idx < A and t_left_idx >= 0:
            min_dist = min(min_dist, distance(temples[t_left_idx], shrines[s_right_idx]) + max(0, shrines[s_right_idx] - x))

        results.append(min_dist)

    return results

def main():
    input = sys.stdin.read
    data = input().split()

    A = int(data[0])
    B = int(data[1])
    Q = int(data[2])

    shrines = [int(data[i]) for i in range(3, 3 + A)]
    temples = [int(data[i]) for i in range(3 + A, 3 + A + B)]
    queries = [int(data[i]) for i in range(3 + A + B, len(data))]

    results = find_min_distance(A, B, Q, shrines, temples, queries)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
