def min_replacements_for_beauty(n, s, m):
    # Initialize arrays for dynamic programming
    dp = [[0] * 2 for _ in range(n + 1)]
    replacements = [[0] * 2 for _ in range(n + 1)]

    # Precompute the number of '?' and valid positions for 'a' or 'b'
    a_count = [0] * (n + 1)
    b_count = [0] * (n + 1)

    for i in range(1, n + 1):
        a_count[i] = a_count[i - 1] + (s[i - 1] == '?')
        b_count[i] = b_count[i - 1] + (s[i - 1] != 'a' and s[i - 1] != '?')

        if i >= m:
            # Check for valid occurrence of t ending at position i
            if (i % 2 == 0) == (m % 2 == 0):
                dp[i][0], replacements[i][0] = dp[i - m][1], replacements[i - m][1]
            else:
                dp[i][0], replacements[i][0] = dp[i - m][0], replacements[i - m][0]

            # Update the maximum beauty and minimum replacements
            if s[i - m:i] == ('a' * ((m + 1) // 2) + 'b' * (m // 2)).replace('?', '') or \
               all(c in 'ab?' for c in s[i - m:i]):
                if dp[i][0] < dp[i - m][1] + 1:
                    dp[i][0], replacements[i][0] = dp[i - m][1] + 1, replacements[i - m][1] + a_count[i] - a_count[i - m]
                elif dp[i][0] == dp[i - m][1] + 1:
                    replacements[i][0] = min(replacements[i][0], replacements[i - m][1] + a_count[i] - a_count[i - m])

            # Update the current position without considering t
            if dp[i][1] < dp[i - 1][0]:
                dp[i][1], replacements[i][1] = dp[i - 1][0], replacements[i - 1][0]
            elif dp[i][1] == dp[i - 1][0]:
                replacements[i][1] = min(replacements[i][1], replacements[i - 1][0])

            # Update the current position without considering t and with one more replacement
            if s[i - 1] != 'a':
                if dp[i][1] < dp[i - 1][1] + 1:
                    dp[i][1], replacements[i][1] = dp[i - 1][1] + 1, replacements[i - 1][1] + (s[i - 1] == '?')
                elif dp[i][1] == dp[i - 1][1] + 1:
                    replacements[i][1] = min(replacements[i][1], replacements[i - 1][1] + (s[i - 1] == '?'))

            if s[i - 1] != 'b':
                if dp[i][1] < dp[i - 1][1] + 1:
                    dp[i][1], replacements[i][1] = dp[i - 1][1] + 1, replacements[i - 1][1] + (s[i - 1] == '?')
                elif dp[i][1] == dp[i - 1][1] + 1:
                    replacements[i][1] = min(replacements[i][1], replacements[i - 1][1] + (s[i - 1] == '?'))

    # The answer is the minimum number of replacements for maximum beauty
    return replacements[n][0]

