def palindromic_characteristics(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    count = [0] * (n + 1)

    # All substrings of length 1 are 1-palindrome
    for i in range(n):
        dp[i][i] = 1

    # Check all substrings of length > 1
    for length in range(2, n + 1):  # length of substring
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i][(i + j) // 2] if (j - i + 1) % 2 == 0 else dp[i+1][(i + j) // 2]
            count[dp[i][j]] += 1

    # Calculate the palindromic characteristics
    result = [0] * n
    for k in range(n, 0, -1):
        result[k-1] = count[k]
        if k < n:
            count[k-1] += count[k]

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    s = input().strip()
    palindromic_characteristics(s)
