def count_tilings(N, M):
    if N % 2 == 1:
        return pow(2, M, MOD)

    dp = [[0] * (N + 1) for _ in range(M + 1)]
    dp[0][0] = 1

    for m in range(1, M + 1):
        for n in range(N + 1):
            if n >= 2:
                dp[m][n] += dp[m-1][n-2]
            if n == N:
                dp[m][n] += dp[m-1][0]
            else:
                dp[m][n] += dp[m-1][n+2]
            dp[m][n] %= MOD

    return dp[M][0]

