            if city_map[n-i-1][j] == '.' and (down[n-i][j] or (n-i > 1 and down[n-i+2][j])):
                down[n-i-1][j] = True

    # Fill reachability from left and right
    for i in range(n):
        if city_map[i][0] == '.':
            left[i][0] = True
        if city_map[i][m-1] == '.':
            right[i][m-1] = True

    for j in range(1, m):
        for i in range(n):
            if city_map[i][j] == '.' and (left[i][j-1] or (j > 1 and left[i][j-2])):
                left[i][j] = True
            if city_map[i][m-j-1] == '.' and (right[i][m-j] or (m-j > 1 and right[i][m-j+2])):
                right[i][m-j-1] = True

    # Count valid pipes
    ways = 0

    # Horizontal segments with one turn
    for i in range(1, n-1):
        for j in range(1, m-1):
            if city_map[i][j] == '.':
                if up[i][j] and down[i][j]:
                    ways += left[i][j+1] + right[i][j+1]
                if left[i][j] and right[i][j]:
                    ways += up[i+1][j] + down[i+1][j]

    # Vertical segments with one turn
    for j in range(1, m-1):
        for i in range(1, n-1):
            if city_map[i][j] == '.':
                if left[i][j] and right[i][j]:
                    ways += up[i+1][j] + down[i+1][j]
                if up[i][j] and down[i][j]:
                    ways += left[i][j+1] + right[i][j+1]

    # L-shaped pipes
    for i in range(1, n-1):
        for j in range(2, m):
            if city_map[i][j] == '.':
                if up[i][j] and left[i][j]:
                    ways += 1
                if down[i][j] and left[i][j]:
                    ways += 1

    for i in range(1, n-1):
        for j in range(m-2):
            if city_map[i][j] == '.':
                if up[i][j] and right[i][j]:
                    ways += 1
                if down[i][j] and right[i][j]:
                    ways += 1

    for j in range(1, m-1):
        for i in range(2, n):
            if city_map[i][j] == '.':
                if left[i][j] and up[i][j]:
                    ways += 1
                if left[i][j] and down[i][j]:
                    ways += 1

    for j in range(1, m-1):
        for i in range(n-2):
            if city_map[i][j] == '.':
                if right[i][j] and up[i][j]:
                    ways += 1
                if right[i][j] and down[i][j]:
                    ways += 1

    # Straight pipes along edges
    for j in range(2, m):
        if city_map[0][j] == '.' and city_map[n-1][j] == '.':
            ways += 1

    for i in range(2, n):
        if city_map[i][0] == '.' and city_map[i][m-1] == '.':
            ways += 1

    return ways


