import sys
from itertools import product

def parse_input():
    t = int(input())
    chats = []

    for _ in range(t):
        n = int(input())
        usernames = input().split()
        m = int(input())
        messages = [input() for _ in range(m)]

        chats.append((n, usernames, m, messages))

    return chats

def is_valid_assignment(chat, assignment):
    n, usernames, m, messages = chat
    prev_sender = None

    for i, (msg, sender) in enumerate(zip(messages, assignment)):
        if sender == '?':
            continue

        # Check if the current sender mentions themselves
        text = msg.split(':', 1)[1]
        if any(word in text for word in usernames if word != sender):
            return False

        # Check if two consecutive messages have the same sender
        if prev_sender and prev_sender == sender:
            return False

        prev_sender = sender

    return True

def recover_senders(chat):
    n, usernames, m, messages = chat
    possible_senders = []

    for msg in messages:
        username, text = (msg.split(':', 1) + [''])[:2]

        if username == '?':
            # Find all users who do not mention themselves in the message
            valid_users = [user for user in usernames if all(word != user for word in text.split() if word in usernames)]
            possible_senders.append(valid_users)
        else:
            possible_senders.append([username])

    # Try all combinations of senders for messages with unknown sender
    for assignment in product(*possible_senders):
        if is_valid_assignment(chat, assignment):
            return list(assignment)

    return None

def main():
    chats = parse_input()
    results = []

    for chat in chats:
        result = recover_senders(chat)

        if not result:
            results.append("Impossible")
        else:
            n, usernames, m, messages = chat
            recovered_messages = [
                f"{result[i]}:{messages[i].split(':', 1)[1]}" 
                for i in range(m)
            ]
            results.extend(recovered_messages)

    for line in results:
        print(line)

if __name__ == "__main__":
    main()
