        lines = set()
        for i in range(n):
            intercept = y[i] - slope * i
            lines.add(intercept)
        return len(lines) == 2

    if n < 3:
        return "No"

    # Check slopes between first three points to determine possible parallel lines
    if is_possible((y[1] - y[0])):
        return "Yes"
    if is_possible((y[2] - y[1])):
        return "Yes"
    if is_possible((y[2] - y[0]) / 2):
        return "Yes"

    return "No"


