    reverse_graph = [[] for _ in range(n)]

    for _ in range(m):
        s, t = map(int, input().split())
        graph[s].append(t)
        reverse_graph[t].append(s)

    visited = [False] * n
    order = []
    for i in range(n):
        if not visited[i]:
            dfs(i)

    component_id = [-1] * n
    max_satisfaction = [0] * n
    k = 0

    for v in reversed(order):
        if component_id[v] == -1:
            rdfs(v, k)
            k += 1

