        color_top = blanket[x][y]
        color_middle = blanket[x + height][y]
        color_bottom = blanket[x + 2 * height][y]

        if color_top == color_middle or color_middle == color_bottom:
            return False

        for j in range(y, m):
            if (blanket[x][j] != color_top or
