def count_special_subsequences():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    A = list(map(int, data[2:]))

    prefix_sum_mod_k = [0] * (N + 1)
    for i in range(1, N + 1):
        prefix_sum_mod_k[i] = (prefix_sum_mod_k[i - 1] + A[i - 1]) % K

    count = 0
    mod_count = {}

    for i in range(N + 1):
        target_mod = (prefix_sum_mod_k[i] - i) % K
        if target_mod < 0:
            target_mod += K

        if target_mod in mod_count:
            count += mod_count[target_mod]

        if target_mod not in mod_count:
            mod_count[target_mod] = 0

        mod_count[target_mod] += 1

        if i >= K:
            old_target_mod = (prefix_sum_mod_k[i - K] - (i - K)) % K
            if old_target_mod < 0:
                old_target_mod += K

            mod_count[old_target_mod] -= 1

    print(count)

