def count_perfectly_balanced_striped_bsts(n):
    if n % 2 == 0:
        return 0

    def is_perfectly_balanced_and_striped(k, left_parity):
        if k == 1:
            return True

        # Calculate the number of nodes in the left and right subtrees
        left_size = (k - 1) // 2
        right_size = k - 1 - left_size

        # Check if both subtrees are perfectly balanced and striped
        if not is_perfectly_balanced_and_striped(left_size, not left_parity):
            return False
        if not is_perfectly_balanced_and_striped(right_size, left_parity):
            return False

        return True

    def count_trees(k, left_parity):
        if k == 1:
            return 1

        # Calculate the number of nodes in the left and right subtrees
        left_size = (k - 1) // 2
        right_size = k - 1 - left_size

        # Count valid trees for both subtrees
        count_left = count_trees(left_size, not left_parity)
        count_right = count_trees(right_size, left_parity)

        return (count_left * count_right) % MOD

    if is_perfectly_balanced_and_striped(n, True):
        return count_trees(n, True)

    return 0

