def count_valid_strings(N):
    dp = [[[[0 for _ in range(4)] for _ in range(4)] for _ in range(4)] for _ in range(N+1)]

    # Initialize base case: strings of length 1
    for i in range(4):
        dp[1][i][i][i] = 1

    # Fill the DP table
    for n in range(2, N + 1):
        for a in range(4):
            for b in range(4):
                for c in range(4):
                    if [a, b, c] != [0, 1, 2]:  # AGC is not allowed as a substring
                        for d in range(4):
                            dp[n][b][c][d] = (dp[n][b][c][d] + dp[n-1][a][b][c]) % MOD

    result = 0
    for a in range(4):
        for b in range(4):
            for c in range(4):
                result = (result + dp[N][a][b][c]) % MOD

    return result

if __name__ == "__main__":
    N = int(input())
    print(count_valid_strings(N))
