def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    S = list(map(int, data[1:]))

    from collections import Counter

    # Count occurrences of each health value in S
    count = Counter(S)

    def can_partition(n):
        if n == 0:
            return True

        max_health = max(count.keys())

        for h in range(max_health, 0, -1):
            if count[h] > 2**(n-1):
                continue

            # Try to use this health value as the parent
            count[h] -= 1
            left_count = Counter()

            for k in count:
                if k < h:
                    left_count[k] += count[k]

            if sum(left_count.values()) == 2**(n-1):
                if can_partition(n-1):
                    return True

            # Backtrack
            count[h] += 1

        return False

    if can_partition(N):
        print("Yes")
    else:
        print("No")

