def max_payment(n, m, coupons):
    # Sort coupons by value in descending order
    coupons.sort(key=lambda x: -x[1])

    def can_construct(k):
        # Calculate the maximum number of distinct elements we can use
        if k % 2 == 0:
            return (k * (k - 1) // 2) + (k // 2)
        else:
            return (k * (k - 1) // 2) + ((k + 1) // 2)

    # Binary search for the maximum number of coupons we can use
    left, right = 0, m
    while left < right:
        mid = (left + right + 1) // 2
        if can_construct(mid) <= n:
            left = mid
        else:
            right = mid - 1

    # Calculate the maximum payment using the best number of coupons
    max_coupons = left
    return sum(coupons[i][1] for i in range(max_coupons))

