    while left < right:
        mid = (left + right + 1) // 2
        if can_construct(mid) <= n:
            left = mid
        else:
            right = mid - 1

    # Calculate the maximum payment using the top 'left' coupons
    max_payment = sum(coupons[i][1] for i in range(left))

    return max_payment

