def count_polygons(R, C):
    def is_polygon(mask):
        # Check if mask forms a single polygon
        visited = [[False] * C for _ in range(R)]

        def dfs(x, y):
            stack = [(x, y)]
            while stack:
                cx, cy = stack.pop()
                if not (0 <= cx < R and 0 <= cy < C) or visited[cx][cy]:
                    continue
                visited[cx][cy] = True
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < R and 0 <= ny < C and mask[nx][ny]:
                        stack.append((nx, ny))

        # Find the first chocolate to start DFS
        for i in range(R):
            for j in range(C):
                if mask[i][j]:
                    dfs(i, j)
                    break
            else:
                continue
            break

        # Check if all chocolates are visited
        for i in range(R):
            for j in range(C):
                if mask[i][j] and not visited[i][j]:
                    return False
        return True

    def generate_masks():
        masks = []
        total_cells = R * C
        for num in range(1, 2**total_cells):
