import sys
from collections import deque, defaultdict

def build_automaton(taboos):
    MAX_LEN = 10  # Maximum length of taboo strings to consider for building automaton
    trie = [{}]

    def insert(word):
        node = 0
        for char in word:
            if char not in trie[node]:
                trie.append({})
                trie[node][char] = len(trie) - 1
            node = trie[node][char]
        return node

    # Insert all taboo strings into the trie
    for taboo in taboos:
        insert(taboo)

    # Build failure links using BFS
    queue = deque()
    for char, next_node in trie[0].items():
        queue.append(next_node)
        trie[next_node]['fail'] = 0

    while queue:
        current = queue.popleft()
        for char, next_node in trie[current].items():
            if char == 'fail':
                continue
            fail_state = trie[current]['fail']
            while fail_state and char not in trie[fail_state]:
                fail_state = trie[fail_state]['fail']
            trie[next_node]['fail'] = trie[fail_state].get(char, 0)
            queue.append(next_node)

    return trie

def find_longest_clue(trie):
    # Check if there's a state that can't reach the end of any taboo
    def can_reach_end(state):
        visited = set()
        stack = [state]
        while stack:
            current = stack.pop()
            if 'end' in trie[current]:
                return True
            for char, next_state in trie[current].items():
                if char == 'fail':
                    continue
                if next_state not in visited:
                    visited.add(next_state)
                    stack.append(next_state)
        return False

    # Find the longest string that doesn't contain any taboo as a substring
    def dfs(state, path):
        nonlocal max_length, result

        if len(path) > max_length and can_reach_end(state):
            max_length = len(path)
            result = path[:]

        for char in '01':
            next_state = state
            while next_state and char not in trie[next_state]:
                next_state = trie[next_state]['fail']
            next_state = trie[next_state].get(char, 0)

            if can_reach_end(next_state):
                dfs(next_state, path + char)

    max_length = -1
    result = []
    dfs(0, "")

    return ''.join(result) if max_length != -1 else '-1'

def main():
    n = int(input().strip())
    taboos = [input().strip() for _ in range(n)]

    trie = build_automaton(taboos)

    # Mark end states of taboo strings
    def mark_end_states(state):
        if 'end' in trie[state]:
            return
        if any(char not in trie[state] for char in '01'):
            trie[state]['end'] = True
            return
        for char in '01':
            next_state = state
            while next_state and char not in trie[next_state]:
                next_state = trie[next_state]['fail']
            mark_end_states(trie[next_state].get(char, 0))

    mark_end_states(0)

    result = find_longest_clue(trie)
    print(result)

