            current = stack.pop()
            if 'end' in trie[current]:
                return True
            for char, next_state in trie[current].items():
                if char == 'fail':
                    continue
                if next_state not in visited:
                    visited.add(next_state)
                    stack.append(next_state)
        return False

    # Check if there's a state that can't reach any taboo string of length <= MAX_LEN
    def is_safe(state):
        for i in range(1, MAX_LEN + 1):
            if 'end' in trie[state] and len(trie[state]['end']) == i:
                return False
        return True

    # BFS to find the longest safe state
    queue = deque([0])
    max_length = -1
    best_state = None

    while queue:
        current = queue.popleft()
        if is_safe(current):
            length = 0
            node = current
            while 'fail' in trie[node]:
                node = trie[node]['fail']
                length += 1
            if length > max_length:
                max_length = length
                best_state = current

        for char, next_state in trie[current].items():
