MOD = 1000000007

def count_sequences(a11, a12, a21, a22, N):
    # Total players for each skill
    total_1 = a11 + a12
    total_2 = a21 + a22

    if total_1 == 0 or total_2 == 0:
        return 0

    # Initialize DP table
    dp = [[[0] * (N + 1) for _ in range(3)] for _ in range(3)]

    # Base cases: sequences of length 1
    if total_1 > 0 and total_2 > 0:
        dp[1][0][1] = a11 * a21 + a12 * a22
        dp[2][0][1] = a21 * a11 + a22 * a12

    # Fill DP table for sequences of length 2 to N
    for length in range(2, N + 1):
        # Transition from (attacker, defender) to next move
        for attacker in [1, 2]:
            for rest_count in range(3):
                if dp[attacker][rest_count][length - 1] > 0:
                    # If the attacker can continue attacking
                    if rest_count < 2:
                        new_rest = rest_count + 1
                        other_attacker = 3 - attacker
                        for defender in [1, 2]:
                            if attacker != defender:
                                dp[attacker][new_rest][length] += (
                                    dp[attacker][rest_count][length - 1] *
                                    (total_1 if other_attacker == 1 else total_2)
                                ) % MOD
                                dp[attacker][new_rest][length] %= MOD

                    # If the attacker must rest, choose a new pair
                    if rest_count == 2:
                        for new_attacker in [1, 2]:
                            if new_attacker != attacker:
                                for defender in [1, 2]:
                                    if new_attacker != defender:
                                        dp[new_attacker][0][length] += (
                                            dp[attacker][rest_count][length - 1] *
                                            (total_1 if new_attacker == 1 else total_2)
                                        ) % MOD
                                        dp[new_attacker][0][length] %= MOD

    # Sum up all valid sequences of length N
    result = sum(dp[attacker][rest_count][N] for attacker in [1, 2] for rest_count in range(3)) % MOD

    return result

