def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    p = int(data[2])

    board = []
    index = 3
    for i in range(n):
        row = list(map(int, data[index:index + m]))
        board.append(row)
        index += m

    def increment(x, y):
        nonlocal board
        for i in range(n):
            board[i][y] = (board[i][y] % p) + 1
        for j in range(m):
            board[x][j] = (board[x][j] % p) + 1

    def is_won():
        return all(all(cell == p for cell in row) for row in board)

    moves = []

    # Try to solve by incrementing each column first
    for col in range(m):
        target = [row[col] for row in board]
        for i in range(n):
            if target[i] != p:
                needed = (p - target[i]) % p
                for _ in range(needed):
                    moves.append(i * m + col + 1)
                    increment(i, col)

    # Check if the game is won after column operations
    if not is_won():
        board = [row[:] for row in [[board[i][j] - (p-1) % p for j in range(m)] for i in range(n)]]

        # Try to solve by incrementing each row next
        for row in range(n):
            target = board[row]
            for col in range(m):
                if target[col] != p:
                    needed = (p - target[col]) % p
                    for _ in range(needed):
                        moves.append(row * m + col + 1)
                        increment(row, col)

    # Final check if the game is won
