def count_routes():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])
    roads = [(int(data[i*2+2]), int(data[i*2+3])) for i in range(M)]

    from collections import defaultdict, deque

    graph = defaultdict(list)
    indegree = [0] * (N + 1)

    for A, B in roads:
        graph[A].append(B)
        indegree[B] += 1

    # Check for cycles
    def has_cycle():
        visited = [False] * (N + 1)
        rec_stack = [False] * (N + 1)

        def dfs(v):
            visited[v] = True
            rec_stack[v] = True

            for neighbor in graph[v]:
                if not visited[neighbor]:
                    if dfs(neighbor):
                        return True
                elif rec_stack[neighbor]:
                    return True

            rec_stack[v] = False
            return False

        for node in range(1, N + 1):
            if not visited[node]:
                if dfs(node):
                    return True
        return False

    if has_cycle():
        print("inf")
        return

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(1, N + 1):
        if indegree[i] == 0:
            queue.append(i)

    dp = [0] * (N + 1)
    dp[1] = 1

    while queue:
        node = queue.popleft()

        for neighbor in graph[node]:
            dp[neighbor] += dp[node]
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    result = dp[2] % 1000000000
    print(result)

