    n, k, m, a = map(int, input().split())
    votes = list(map(lambda x: int(x) - 1, input().split()))

    candidates = [{'votes': 0, 'last_vote_time': float('inf'), 'index': i} for i in range(n)]

    for time, candidate_index in enumerate(votes):
        candidates[candidate_index]['votes'] += 1
        candidates[candidate_index]['last_vote_time'] = time

    def compare(c1, c2):
        if c1['votes'] != c2['votes']:
            return c2['votes'] - c1['votes']
        else:
            return c1['last_vote_time'] - c2['last_vote_time']

    candidates.sort(key=lambda x: (x['votes'], -x['last_vote_time']), reverse=True)

    results = [0] * n

    for i, candidate in enumerate(candidates):
        if candidate['votes'] == 0 and m - a == 0:
            results[candidate['index']] = 3
            continue

        remaining_votes_needed = sum(1 for c in candidates[:k] if c != candidate) + 1
        possible_max_votes = candidate['votes'] + (m - a)

        if i < k and possible_max_votes > 0:
            results[candidate['index']] = 1
        elif remaining_votes_needed <= m - a:
            temp_candidates = candidates[:]
            temp_candidates[i]['votes'] += m - a

            temp_candidates.sort(key=lambda x: (x['votes'], -x['last_vote_time']), reverse=True)

            if any(temp_candidates.index(candidate) < k for candidate in temp_candidates):
                results[candidate['index']] = 2
        else:
            results[candidate['index']] = 3

    print(' '.join(map(str, results)))

