import sys
from math import sqrt

def min_total_distance():
    ax, ay, bx, by, tx, ty = map(int, input().split())
    n = int(input())

    bottles = [tuple(map(int, input().split())) for _ in range(n)]

    def distance(x1, y1, x2, y2):
        return sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

    total_distance = 0
    adil_savings = [float('inf')] * n
    bera_savings = [float('inf')] * n

    for i, (xi, yi) in enumerate(bottles):
        dist_to_bin = distance(xi, yi, tx, ty)
        total_distance += 2 * dist_to_bin

        adil_dist = distance(ax, ay, xi, yi)
        bera_dist = distance(bx, by, xi, yi)

        adil_savings[i] = adil_dist - dist_to_bin
        bera_savings[i] = bera_dist - dist_to_bin

    min_distance = total_distance

    for i in range(n):
        min_distance = min(min_distance, total_distance + adil_savings[i])

    for j in range(n):
        min_distance = min(min_distance, total_distance + bera_savings[j])

    for i in range(n):
        for j in range(n):
            if i != j:
                combined_saving = adil_savings[i] + bera_savings[j]
                min_distance = min(min_distance, total_distance + combined_saving)

    print(f"{min_distance:.12f}")

if __name__ == "__main__":
    min_total_distance()
