from collections import defaultdict, deque
import sys

def min_time_to_cross(P, R, L, logs):
    graph = defaultdict(list)

    for E1, E2 in logs:
        graph[E1].append(E2)
        graph[E2].append(E1)

    def bfs(start, end):
        queue = deque([(start, 0)])
        visited = set([start])

        while queue:
            node, time = queue.popleft()

            if node == end:
                return time

            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, time + 1))

        return float('inf')

    def can_cross_all():
        min_time = bfs(-2, -1)
        if min_time == float('inf'):
            return False, P

        people_left = P
        current_position = -2

        while people_left > 0:
            time_to_cross = bfs(current_position, -1)
            if time_to_cross == float('inf'):
                break

            people_left -= 1
            current_position = -1
            total_time += time_to_cross

            # Remove the used plank
            for E1 in graph:
                graph[E1] = [E2 for E2 in graph[E1] if bfs(E1, E2) != time_to_cross]

        return people_left == 0, P - people_left

    total_time = 0
    can_all_cross, left_behind = can_cross_all()

    if can_all_cross:
        return total_time
    else:
        return f"{left_behind} people left behind"

