import sys

def min_time_to_cross(P, R, L, logs):
    graph = defaultdict(list)

    for e1, e2 in logs:
        graph[e1].append(e2)
        graph[e2].append(e1)

    def bfs(start, end):
        queue = deque([(start, 0)])
        visited = set([start])

        while queue:
            node, time = queue.popleft()

            if node == end:
                return time

            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, time + 1))

        return float('inf')

    def can_cross_all():
        min_time = bfs(-2, -1)

        if min_time == float('inf'):
            return False, P

        remaining_people = P
        current_position = -1
        total_time = 0

        while remaining_people > 0:
            # Find the farthest boulder from the right bank that can be reached
            max_distance = -1
            next_boulder = None

            for node in range(-2, R):
                if node != current_position and node != -1:
                    distance = bfs(node, -1)
                    if 0 < distance <= remaining_people and distance > max_distance:
                        max_distance = distance
                        next_boulder = node

            if next_boulder is None:
                break

            # Move people to the farthest boulder
            total_time += 2 * (bfs(current_position, next_boulder) - 1)
            current_position = next_boulder
            remaining_people -= max_distance

        if remaining_people == 0:
            return True, total_time + bfs(current_position, -1)

        return False, remaining_people

    can_cross, result = can_cross_all()

    if can_cross:
        print(result)
    else:
        print(f"{result} people left behind")

def main():
