import sys
from collections import defaultdict, deque

def compute_success_probability():
    n = int(input().strip())
    l = int(input().strip())
    captain_path = list(map(int, input().strip().split()))

    graph = defaultdict(list)
    for i in range(n):
        neighbors = list(map(int, input().strip().split()))[1:]
        graph[i] = neighbors

    # Initialize DP table
    dp = [[[-1.0 for _ in range(n)] for _ in range(n)] for _ in range(l + 1)]

    def dfs(step, captain_pos, sentry_pos):
        if step == l:
            return 1.0

        if dp[step][captain_pos][sentry_pos] != -1.0:
            return dp[step][captain_pos][sentry_pos]

        next_captain_pos = captain_path[step]
        probability = 0.0
        total_ways = len(graph[sentry_pos])

        if total_ways == 0:
            return 0.0

        for next_sentry_pos in graph[sentry_pos]:
            if next_sentry_pos == next_captain_pos or next_sentry_pos == captain_pos:
                continue

            probability += dfs(step + 1, next_captain_pos, next_sentry_pos) / total_ways

        dp[step][captain_pos][sentry_pos] = probability
        return probability

    # Start DFS from the first room in the captain's path
    initial_probability = dfs(0, captain_path[0], 0)

    for sentry_start in range(n):
        if sentry_start != captain_path[0]:
            total_ways = len(graph[sentry_start])
            if total_ways > 0:
                for next_sentry_pos in graph[sentry_start]:
                    initial_probability += dfs(1, captain_path[1], next_sentry_pos) / total_ways

    print(f"{initial_probability:.7f}")

compute_success_probability()
