import math

def calculate_area(a, b, c):
    # Check if a triangle with sides a, b, c can exist using the triangle inequality theorem
    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    # Calculate semi-perimeter of the triangle formed by distances to corners
    s = (a + b + c) / 2.0

    # Calculate area of the triangle using Heron's formula
    try:
        area_triangle = math.sqrt(s * (s - a) * (s - b) * (s - c))
    except ValueError:
        return -1

    # Using the formula for the area of an equilateral triangle with side length s:
    # Area = (sqrt(3)/4) * s^2
    # We can relate this to our problem using the distances from the stain to the corners.

    # Calculate the area of the equilateral triangle carpet
    # Using the formula: Area_carpet = sqrt(s*(s-a)*(s-b)*(s-c)) / (0.25 * sqrt(3))
    try:
        area_carpet = area_triangle / (0.25 * math.sqrt(3))
    except ZeroDivisionError:
        return -1

    return round(area_carpet, 9)

def main():
    a, b, c = map(float, input().split())
    result = calculate_area(a, b, c)
    print(result)

