from math import sqrt, isclose

def calculate_distance(p1, p2):
    return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def line_length(points):
    length = 0.0
    for i in range(len(points)):
        length += calculate_distance(points[i], points[(i + 1) % len(points)])
    return length

def is_valid_division(positive, negative):
    if not positive or not negative:
        return False
    pos_sum = sum(p[2] for p in positive)
    neg_sum = sum(n[2] for n in negative)
    return abs(pos_sum + neg_sum) < 1e-6

def find_dividing_line(lamps):
    min_length = float('inf')
    found = False

    for subset in itertools.chain.from_iterable(itertools.combinations(lamps, r) for r in range(len(lamps)+1)):
        positive = [lamp for lamp in subset if lamp[2] > 0]
        negative = [lamp for lamp in lamps if lamp not in subset and lamp[2] < 0]

        if is_valid_division(positive, negative):
            found = True
            points = [(lamp[0], lamp[1]) for lamp in positive + negative]
            min_length = min(min_length, line_length(points))

    return min_length if found else "IMPOSSIBLE"

def main():
