import itertools
from math import sqrt, isclose

def calculate_distance(p1, p2):
    return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def line_length(points):
    length = 0.0
    for i in range(len(points)):
        length += calculate_distance(points[i], points[(i + 1) % len(points)])
    return length

def is_valid_line(lamps, line_points):
    inside_sum = outside_sum = 0
    for x, y, e in lamps:
        if any(min(px, px2) <= x <= max(px, px2) and min(py, py2) <= y <= max(py, py2)
               for (px, py), (px2, py2) in zip(line_points, line_points[1:] + [line_points[0]])):
            inside_sum += e
        else:
            outside_sum += e
    return isclose(inside_sum, -outside_sum)

def find_balancing_line(lamps):
    x_coords = sorted(set(x for x, _, _ in lamps))
    y_coords = sorted(set(y for _, y, _ in lamps))

    min_length = float('inf')
    found = False

    for i in range(len(x_coords) - 1):
        for j in range(len(y_coords) - 1):
            line_points = [(x_coords[i], y_coords[j]), (x_coords[i + 1], y_coords[j]),
                           (x_coords[i + 1], y_coords[j + 1]), (x_coords[i], y_coords[j + 1])]

            if is_valid_line(lamps, line_points):
                found = True
                min_length = min(min_length, line_length(line_points))

    return min_length if found else "IMPOSSIBLE"

def main():
    n = int(input())
    lamps = [tuple(map(int, input().split())) for _ in range(n)]

    result = find_balancing_line(lamps)
    print(result)

