    animal_count = {}
    target_enclosure = {}

    for i, enclosure in enumerate(enclosures):
        correct_animal = enclosure[0]
        num_animals = int(enclosure[1])

        if correct_animal not in animal_count:
            animal_count[correct_animal] = 0
            target_enclosure[correct_animal] = []

        for j in range(2, 2 + num_animals):
            animal_type = enclosure[j]
            animal_count[animal_type] = animal_count.get(animal_type, 0) + 1
            if animal_type != correct_animal:
                target_enclosure[correct_animal].append((i, animal_type))

    # Check if we can move animals to their correct enclosures
    def can_move():
        visited = set()

        def dfs(start):
            stack = [start]
            while stack:
                current = stack.pop()
                if current in visited:
                    continue
                visited.add(current)

                enclosure_index, animal_type = current
                for target_enclosure_index, target_animal_type in target_enclosure[animal_type]:
                    if target_enclosure_index not in visited and animal_count[target_animal_type] > 0:
                        stack.append((target_enclosure_index, target_animal_type))

        # Start DFS from any enclosure with misplaced animals
        for i, enclosure in enumerate(enclosures):
            correct_animal = enclosure[0]
            num_animals = int(enclosure[1])

            if animal_count.get(correct_animal, 0) < sum(1 for j in range(2, 2 + num_animals) if enclosure[j] == correct_animal):
                dfs((i, correct_animal))

        # Check if all misplaced animals can be moved
        for i, enclosure in enumerate(enclosures):
            correct_animal = enclosure[0]
            num_animals = int(enclosure[1])

            if animal_count.get(correct_animal, 0) < sum(1 for j in range(2, 2 + num_animals) if enclosure[j] == correct_animal):
