            for j in range(2, 2 + num_animals):
                animal_type = enclosure[j]
                if animal_type != correct_animal and (i, animal_type) not in visited:
                    return False

        return True

    # Check if all animals are already in their proper enclosures
    all_in_place = True
    for i, enclosure in enumerate(enclosures):
        correct_animal = enclosure[0]
        num_animals = int(enclosure[1])

        if animal_count.get(correct_animal, 0) < sum(1 for j in range(2, 2 + num_animals) if enclosure[j] == correct_animal):
            all_in_place = False
            break

    if all_in_place:
        print("FALSE ALARM")
    elif can_move():
        print("POSSIBLE")
    else:
        print("IMPOSSIBLE")

