    for i in range(2, MAX_K + 1):
        x = i
        for j in range(2, i + 1):
            while x % j == 0:
                prime_factors_count[i][j] += 1
                x //= j

    # Accumulate the counts from smaller factorials to larger ones
    for i in range(2, MAX_K + 1):
        for j in range(2, i + 1):
            prime_factors_count[i][j] += prime_factors_count[i - 1][j]

