import sys
from collections import defaultdict, deque

def min_cost_message():
    message = input().strip()
    n = int(input().strip())

    stickers = []
    for _ in range(n):
        sticker_info = input().split()
        word = sticker_info[0]
        price = int(sticker_info[1])
        stickers.append((word, price))

    # Initialize DP array
    dp = [float('inf')] * (len(message) + 1)
    dp[0] = 0

    for i in range(len(message) + 1):
        if dp[i] == float('inf'):
            continue

        # Try to place one sticker starting at position i
        for word, price in stickers:
            if message.startswith(word, i):
                end_pos = i + len(word)
                if end_pos <= len(message):
                    dp[end_pos] = min(dp[end_pos], dp[i] + price)

        # Try to place two overlapping stickers starting at position i
        for j in range(i + 1, len(message) + 1):
            for word1, price1 in stickers:
                if message.startswith(word1, i):
                    end_pos1 = i + len(word1)
                    for word2, price2 in stickers:
                        if message.startswith(word2, j):
                            end_pos2 = j + len(word2)
                            max_end_pos = max(end_pos1, end_pos2)
                            if max_end_pos <= len(message):
                                dp[max_end_pos] = min(dp[max_end_pos], dp[i] + price1 + price2)

    result = dp[len(message)]
    print(result if result != float('inf') else "IMPOSSIBLE")

min_cost_message()
