import sys
from math import gcd

def find_wcd(n, pairs):
    def get_divisors(x):
        divisors = set()
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                divisors.add(i)
                while x % i == 0:
                    x //= i
        if x > 1:
            divisors.add(x)
        return divisors

    a = pairs[0][0]
    b = pairs[0][1]

    for i in range(1, n):
        a = gcd(a, pairs[i][0])
        b = gcd(b, pairs[i][1])

    common_divisors = get_divisors(a) | get_divisors(b)

    for d in sorted(common_divisors, reverse=True):
        if all((x % d == 0 or y % d == 0) for x, y in pairs):
            return d

    return -1

if __name__ == "__main__":
    n = int(input().strip())
    pairs = [tuple(map(int, input().strip().split())) for _ in range(n)]
