import sys
from math import gcd

def find_wcd(n, pairs):
    def get_divisors(x):
        divisors = set()
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                divisors.add(i)
                while x % i == 0:
                    x //= i
        if x > 1:
            divisors.add(x)
        return divisors

    a = pairs[0][0]
    b = pairs[0][1]

    for i in range(1, n):
        a_i, b_i = pairs[i]
        a = gcd(a, a_i * b_i)
        b = gcd(b, a_i * b_i)

    divisors_a = get_divisors(a)
    divisors_b = get_divisors(b)

    common_divisors = divisors_a.intersection(divisors_b)

    for d in sorted(common_divisors, reverse=True):
        if all((a_i % d == 0 or b_i % d == 0) for a_i, b_i in pairs):
            return d

    return -1

