    # Parse the coordinates of the nails
    coords = []
    index = 0
    for i in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        coords.append((x, y))
        index += 2

    # Parse the directions
    directions = data[index:]

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        points = sorted(set(points))

        if len(points) <= 1:
            return points

        lower = []
        for p in points:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

