def find_best_k(n, a):
    def count_correct_hits(k):
        current = 0
        correct_hits = 0
        for i in range(1, n):
            if a[i] > a[i - 1]:
                current += k
            elif a[i] < a[i - 1]:
                current -= k
            # Check if the current key matches any possible starting point
            if (a[i] - current) % (2 * k) == 0 and abs(a[i] - current) // (2 * k) <= i:
                correct_hits += 1
        return correct_hits

    max_correct_hits = 0
    best_k = 0

    # Try different values of K
    for k in range(1, int(2e9) + 1):
        current_correct_hits = count_correct_hits(k)
        if current_correct_hits > max_correct_hits:
            max_correct_hits = current_correct_hits
            best_k = k

    return max_correct_hits + 1, best_k

