def min_lines_to_cover_holes():
    import sys
    input = sys.stdin.read
    data = list(map(int, input().split()))

    n = data[0]
    points = [(data[i*2+1], data[i*2+2]) for i in range(n)]

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    points.sort()
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    convex_hull = lower[:-1] + upper[:-1]

    def is_collinear(a, b, c):
        return (b[1] - a[1]) * (c[0] - b[0]) == (c[1] - b[1]) * (b[0] - a[0])

    lines = set()
    for i in range(len(convex_hull)):
        for j in range(i + 1, len(convex_hull)):
            if is_collinear(convex_hull[i], convex_hull[j], points[(i + 1) % n]):
                line = (convex_hull[i][0] * convex_hull[j][1] - convex_hull[j][0] * convex_hull[i][1],
                        convex_hull[i][1] - convex_hull[j][1],
                        convex_hull[j][0] - convex_hull[i][0])
                lines.add(line)

    print(len(lines))

