MOD = 998244353

def count_best_friend_pairs(n):
    if n == 1:
        return 10

    dp = [[0] * 11 for _ in range(n + 1)]

    # Base case: single digit numbers are best friends with themselves
    for i in range(10):
        dp[1][i] = 1

    for length in range(2, n + 1):
        for last_digit in range(10):
            if last_digit > 0:
                dp[length][last_digit] += dp[length - 1][last_digit - 1]
            dp[length][last_digit] %= MOD
            if last_digit < 9:
                dp[length][last_digit] += dp[length - 1][last_digit + 1]
            dp[length][last_digit] %= MOD

    total_pairs = sum(dp[n]) % MOD

    # Calculate the number of valid transformations for each length
    def count_transformations(length):
        if length == 1:
            return 10

        transform_dp = [[0] * 11 for _ in range(length + 1)]

        for i in range(10):
            transform_dp[1][i] = 1

        for l in range(2, length + 1):
            for d in range(10):
                if d > 0:
                    transform_dp[l][d] += transform_dp[l - 1][d - 1]
                transform_dp[l][d] %= MOD
                if d < 9:
                    transform_dp[l][d] += transform_dp[l - 1][d + 1]
                transform_dp[l][d] %= MOD

        return sum(transform_dp[length]) % MOD

    valid_transformations = count_transformations(n)

    # Calculate the number of best friend pairs
    result = pow(valid_transformations, n, MOD) * total_pairs % MOD
    return result

