    odd_count = sum(1 for v in count.values() if v % 2 == 1)

    def can_divide(k):
        total_pairs = n - odd_count
        if total_pairs % k != 0:
            return False
        pairs_per_palindrome = total_pairs // k
        required_odds = k - (pairs_per_palindrome * 2)
        return required_odds <= odd_count and required_odds % 2 == 0

    for k in range(1, n + 1):
        if can_divide(k):
            break

    half_length = (n // k) // 2
    palindromes = []

    def build_palindrome():
        palindrome_half = []
        odd_char = ''

        for char, cnt in count.items():
            while cnt > 0 and len(palindrome_half) < half_length:
                if cnt % 2 == 1:
                    odd_char = char
                palindrome_half.append(char)
                cnt -= 2

        return ''.join(palindrome_half), odd_char

    for _ in range(k):
        first_half, odd_char = build_palindrome()
        second_half = first_half[::-1]

        if odd_char:
            palindromes.append(first_half + odd_char + second_half)
            count[odd_char] -= 1
        else:
            palindromes.append(first_half + second_half)

    print(k)
    print(' '.join(palindromes))

