from collections import Counter
import sys

def min_palindromes(n, s):
    count = Counter(s)
    odd_count = sum(1 for c in count if count[c] % 2 == 1)

    def can_divide(k):
        total_odd = odd_count
        length = n // k
        if n % k != 0:
            return False

        half_length = (length + 1) // 2
        needed_odds = k - (total_odd // 2)

        if needed_odds > half_length * k or total_odd < needed_odds:
            return False

        for c in count:
            pairs = count[c] // 2
            if pairs >= half_length:
                continue
            deficit = half_length - pairs
            if deficit <= (total_odd - needed_odds):
                total_odd -= deficit * 2
                count[c] -= deficit * 2
            else:
                total_odd -= (total_odd - needed_odds) * 2
                count[c] -= (total_odd - needed_odds) * 2

        return True

    for k in range(1, n + 1):
        if n % k == 0 and can_divide(k):
            break

    half_length = (n // k + 1) // 2
    palindromes = []
    count = Counter(s)

    for _ in range(k):
        left_half = []
        middle_char = ''

        for c in sorted(count, key=lambda x: -count[x]):
            if count[c] >= 2:
                pairs = count[c] // 2
                left_half.extend([c] * min(pairs, half_length))
                count[c] -= pairs * 2

        if odd_count > 0 and middle_char == '':
            for c in sorted(count):
                if count[c] % 2 == 1:
                    middle_char = c
                    count[c] -= 1
                    break

        palindrome = ''.join(left_half) + middle_char + ''.join(reversed(left_half))
        palindromes.append(palindrome)

    print(k)
    print(' '.join(palindromes))

if __name__ == "__main__":
    n = int(input().strip())
    s = input().strip()
    min_palindromes(n, s)
