from itertools import combinations
import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def on_segment(p, q, r):
    if (q[0] <= max(p[0], r[0]) and q[0] >= min(p[0], r[0]) and
            q[1] <= max(p[1], r[1]) and q[1] >= min(p[1], r[1])):
        return True
    return False

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0
    elif val > 0:
        return 1
    else:
        return 2

def do_intersect(p1, q1, p2, q2):
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)
    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)

    if o1 != o2 and o3 != o4:
        return True

    if o1 == 0 and on_segment(p1, p2, q1):
        return True
    if o2 == 0 and on_segment(p1, q2, q1):
        return True
    if o3 == 0 and on_segment(p2, p1, q2):
        return True
    if o4 == 0 and on_segment(p2, q1, q2):
        return True

    return False

def count_intersections(lines):
    n = len(lines)
    intersections = set()

    for (x0, y0, x1, y1), (u0, v0, u1, v1) in combinations(lines, 2):
        if do_intersect((x0, y0), (x1, y1), (u0, v0), (u1, v1)):
            dx = x1 - x0
            dy = y1 - y0
            du = u1 - u0
            dv = v1 - v0

            if dx * dv == dy * du:
                # Lines are collinear
                points = set()
                points.add((x0, y0))
                points.add((x1, y1))
                points.add((u0, v0))
                points.add((u1, v1))

                for x in range(min(x0, x1, u0, u1), max(x0, x1, u0, u1) + 1):
                    for y in range(min(y0, y1, v0, v1), max(y0, y1, v0, v1) + 1):
                        if (x - x0) * dy == (y - y0) * dx and \
                           (x - u0) * dv == (y - v0) * du:
                            points.add((x, y))
                intersections.update(points)
            else:
                # Lines intersect at a single point
                denom = dx * dv - dy * du
                if denom != 0:
                    x_num = x0 * dy * u1 - x0 * dv * v1 + x1 * dv * v0 - x1 * dy * u0
                    y_num = x0 * du * v1 - x0 * dv * u1 + x1 * dv * u0 - x1 * du * v0
                    x_int = x_num // denom
                    y_int = y_num // denom
                    intersections.add((x_int, y_int))

    if len(intersections) > 100000:
        return -1

    return len(intersections)

def main():
    input_lines = sys.stdin.read().strip().split('\n')
    n = int(input_lines[0])
    lines = [tuple(map(int, line.split())) for line in input_lines[1:n+1]]

    result = count_intersections(lines)
    print(result)

if __name__ == "__main__":
