def is_valid_itinerary(start, end, min_distance, max_heading_range, distances, headings):
    total_distance = sum(distances[start:end])
    if total_distance < min_distance:
        return False

    for i in range(start, end - 1):
        heading_change = abs(headings[i] - headings[i + 1])
        if heading_change > max_heading_range:
            return False
    return True

def find_min_switches(n, t_modes, distances, headings):
    x, y = [0], [0]

    for d, h in zip(distances, headings):
        dx = d * cos(radians(h))
        dy = d * sin(radians(h))
        x.append(x[-1] + dx)
        y.append(y[-1] + dy)

    for i in range(1, n):
        headings[i] = calculate_heading_change(x[i-1], y[i-1], x[i], y[i])

    switches = [0] * n
    for mode in t_modes:
        min_distance, max_heading_range = mode
        last_valid_end = 0

